/**
 * ============================================================================
 * ModManager 核心基础设施.
 * ============================================================================
 * 包含常量,环境探测,日志和独立压缩工具.
 * 对外 API 位于同目录 api.js.
 */

const path = require('path');

// 优先使用 original-fs 绕过 ASAR 补丁并操作真实文件系统.
let originalFs;
try {
	originalFs = require('original-fs');

} catch (error) {
	console.error('[ModManager] original-fs 不可用, 使用 Node fs 回退:', error);
	originalFs = require('fs');
}

const PLUGIN_DIR = 'mods';
const CONFIG_DIR = 'config';
const MOD_ORDER_FILE = 'mod_order.json';

/** 游戏核心归档始终保持最低优先级, 不作为模组加载. */
const SYSTEM_ASARS = ['app.asar', 'app.bak.asar'];

const BACKUP_DIR = 'backups';
const BACKUP_LOCK_FILE = 'backups.lock.json';
const STORAGE_DIR = '_storage';
const SAV_EXT = '.sav';

/**
 * 将 sourceDir 中通过过滤条件的文件打包为 zipPath.
 * @param {string} sourceDir
 * @param {string} zipPath
 * @param {(name: string) => boolean} [filter]
 * @returns {number} 打包的文件数
 */
function zipFiles(sourceDir, zipPath, filter) {
	const AdmZip = require('adm-zip');
	const zip = new AdmZip();
	let count = 0;
	for (const name of originalFs.readdirSync(sourceDir)) {
		if (typeof filter === 'function' && !filter(name)) continue;
		const full = path.join(sourceDir, name);
		try {
			if (originalFs.statSync(full).isFile()) {
				zip.addLocalFile(full);
				count++;
			}
		} catch (error) {
			console.error(`[ModManager] 读取待备份文件失败: ${full}`, error);
		}
	}
	zip.writeZip(zipPath);
	return count;
}

/**
 * 将 zipPath 解压到 destDir, 覆盖同名文件.
 * @param {string} zipPath
 * @param {string} destDir
 */
function unzipTo(zipPath, destDir) {
	const AdmZip = require('adm-zip');
	if (!originalFs.existsSync(destDir)) {
		originalFs.mkdirSync(destDir, { recursive: true });
	}
	new AdmZip(zipPath).extractAllTo(destDir, true);
}

/**
 * 将存档归档中的文件扁平提取到 destDir.
 * 跳过 Steam 云存档标记文件, 避免同步冲突.
 * @param {string} zipPath
 * @param {string} destDir
 * @returns {number} 提取的文件数
 */
function extractSavesFlat(zipPath, destDir) {
	const AdmZip = require('adm-zip');
	const zip = new AdmZip(zipPath);
	if (!originalFs.existsSync(destDir)) {
		originalFs.mkdirSync(destDir, { recursive: true });
	}
	let count = 0;
	for (const entry of zip.getEntries()) {
		if (entry.isDirectory) continue;
		const base = path.basename(entry.entryName);
		if (!base) continue;
		if (base.toLowerCase() === 'steam_autocloud.vdf') continue;
		originalFs.writeFileSync(path.join(destDir, base), entry.getData());
		count++;
	}
	return count;
}

const Env = {
	getResourcesPath() {
		if (process.resourcesPath) return path.normalize(process.resourcesPath);
		try {
			const { app } = require('electron');
			return app?.getAppPath() || process.cwd();
		} catch (error) {
			console.error('[ModManager] 读取 Electron 应用路径失败, 使用默认 resources 路径:', error);
			return path.join(process.cwd(), 'resources');
		}
	},

	getPluginDir() {
		return path.join(this.getResourcesPath(), PLUGIN_DIR);
	}
};

const Logger = {
	info(msg) { console.log(`[ModManager] ${msg}`); },
	debug(msg) { console.log(`[ModManager] ${msg}`); },
	error(msg, err) {
		console.error(`[ModManager] ${msg}${err ? ': ' + (err.message || err) : ''}`);
	}
};

module.exports = {
	originalFs,
	PLUGIN_DIR,
	CONFIG_DIR,
	MOD_ORDER_FILE,
	SYSTEM_ASARS,
	BACKUP_DIR,
	BACKUP_LOCK_FILE,
	STORAGE_DIR,
	SAV_EXT,
	Env,
	Logger,
	zipFiles,
	unzipTo,
	extractSavesFlat,
};
